package com.contextgraph.service; import com.contextgraph.model.*; import com.contextgraph.repository.*; import org.springframework.stereotype.Service; import java.util.*; @Service public class GraphService{final EntityNodeRepository nodes;final GraphRelationRepository rels;final UserRepository users;public GraphService(EntityNodeRepository n,GraphRelationRepository r,UserRepository u){nodes=n;rels=r;users=u;}public List<EntityNode>nodes(String email){return nodes.findByOwnerId(users.findByEmailIgnoreCase(email).orElseThrow().getId());}public List<GraphRelation>relations(Long id){return rels.findAllBySourceNodeIdOrTargetNodeId(id,id);}}